<script lang="ts">
  import { t } from '$lib/i18n';
  import { getAlertTitle, getAlertMessage } from '$lib/utils/alert-copy';
  import Panel from './Panel.svelte'; import Meter from './Meter.svelte';
  import Icon from '$lib/components/Icon.svelte'; import BarChart from '$lib/components/BarChart.svelte'; import LineChart from '$lib/components/LineChart.svelte';
  import { evaluateAlerts } from '$lib/api/alerts';
  import { applyRules } from '$lib/api/rules';
  import { apiPut, apiPatch, apiDelete } from '$lib/api/client';
  import { number as n, text, rows, object, type Model, type Actions, type Row } from './model';
  let { m, a }: { m: Model; a: Actions } = $props();
  let alertType=$state(''); let evaluating=$state(false);
  const alertTypes=['balance_low','credit_high','payment_due','payment_overdue','budget_threshold','budget_exceeded','goal_completed'];
  async function evaluate(){evaluating=true;error='';try{await evaluateAlerts();await a.refresh();a.notify(m.l('Alerts evaluated.','Alertas evaluadas.'));}catch(e){error=e instanceof Error?e.message:String(e);}finally{evaluating=false;}}
  let categoryType=$state(''); let severity=$state(''); let readFilter=$state(''); let expanded=$state(0); let error=$state('');
  const monthly=$derived(object(m.dashboard.monthlySummary));
  const breakdown=$derived(rows(m.dashboard.categoryBreakdown));
  const activeAlerts=$derived(m.alerts.filter(row=>!row.isRead));
  const visibleAlerts=$derived(m.alerts.filter(row=>(!alertType||row.type===alertType)&&(!severity||text(row.severity).toLowerCase()===severity)&&(!readFilter||Boolean(row.isRead)===(readFilter==='read'))));
  async function apply(){try{const result=await applyRules();a.notify(`${result.matched} / ${result.processed}`);await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
  async function toggle(row:Row) {try{error='';await apiPut(`/rules/${row.id}`,{enabled:!row.enabled});await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
  async function read(id?:number) {try{error='';await apiPatch(id?`/alerts/${id}/read`:'/alerts/read-all');await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
  async function remove(id:number) {try{error='';await apiDelete(`/alerts/${id}`);await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
</script>
{#if error}<p class="cp-error" role="alert">{error}</p>{/if}
{#if m.route === 'categorias'}
  <div class="cp-toolbar"><div class="cp-tabs">{#each [['',m.l('Overview','Resumen')],['Ingreso',m.l('Income','Ingresos')],['Gasto',m.l('Expenses','Gastos')]] as [value,label]}<button class:active={categoryType===value} onclick={()=>categoryType=value}>{label}</button>{/each}</div><button class="cp-button" onclick={()=>a.edit('categories')}>+ {m.l('New category','Nueva categoría')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.l('Monthly income','Ingresos del mes')}</span><strong class="cp-cyan">{m.money(monthly.totalIncome)}</strong></div><div class="cp-stat"><span>{m.l('Monthly expenses','Gastos del mes')}</span><strong class="cp-red">{m.money(monthly.totalExpenses)}</strong></div><div class="cp-stat"><span>{m.l('Monthly savings','Ahorro del mes')}</span><strong class="cp-yellow">{m.money(n(monthly.totalIncome)-n(monthly.totalExpenses))}</strong></div></div>
  {#each [['Ingreso',m.l('Income categories','Categorías de ingresos')],['Gasto',m.l('Expense categories','Categorías de gastos')]] as [type,title]}{#if !categoryType||categoryType===type}<Panel {title}><div class="cp-category-grid">{#each m.categories.filter(row=>row.type===type||row.type==='Ambos') as row}<article class="cp-category-tile"><button class="cp-text-button" onclick={()=>a.edit('categories',row)}><Icon name={text(row.icon)||'tag'} size={32}/><strong>{text(row.name)}</strong></button>{#if type==='Gasto'}{@const amount=breakdown.find(c=>n(c.categoryId)===row.id)}<b class="cp-number">{m.money(amount?.total)}</b><Meter value={n(amount?.percentage)} label={text(row.name)} tone="red"/>{:else}<span class="cp-muted">{rows(row.subcategories).length} {m.l('subcategories','subcategorías')}</span>{/if}<div class="cp-subcategories">{#each rows(row.subcategories) as sub}<span>{text(sub.name)}</span>{/each}</div><button class="cp-link" onclick={()=>a.edit('categories',row)}>+ {m.l('Subcategories','Subcategorías')}</button></article>{:else}<p class="cp-empty">{m.l('No categories yet.','Aún no hay categorías.')}</p>{/each}<button class="cp-add-tile" onclick={()=>a.edit('categories',{id:0,type})}><Icon name="plus" size={28}/>{m.l('Add category','Agregar categoría')}</button></div></Panel>{/if}{/each}
{:else if m.route === 'reglas'}
  <div class="cp-toolbar"><div class="cp-stats plain"><div class="cp-stat"><span>{m.l('Active rules','Reglas activas')}</span><strong class="cp-cyan">{m.rules.filter(row=>row.enabled).length}</strong><small>{m.rules.length} {m.l('total','en total')}</small></div><div class="cp-stat"><span>{m.l('Automatic categorization','Clasificación automática')}</span><strong class="cp-yellow">{m.l('Rules engine','Motor de reglas')}</strong></div></div><button class="cp-button" onclick={apply}>{m.l('Apply rules','Aplicar reglas')}</button><button class="cp-button" onclick={()=>a.edit('rules')}>+ {m.l('New rule','Nueva regla')}</button></div>
  <Panel title={m.l('Categorization rules','Reglas de clasificación')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.l('Enabled','Activa')}</th><th>{m.l('Priority','Prioridad')}</th><th>{m.l('Name / condition','Nombre / condición')}</th><th>{m.l('Action','Acción')}</th><th></th></tr></thead><tbody>{#each m.rules as row}<tr><td><button class="cp-switch" class:on={Boolean(row.enabled)} role="switch" aria-checked={Boolean(row.enabled)} aria-label={text(row.name)} onclick={()=>toggle(row)}><span></span></button></td><td class="cp-number">{n(row.priority)}</td><td><b>{text(row.name)}</b>{#each rows(row.conditions) as condition}<small class="cp-condition">{text(condition.field)} {text(condition.operator)} “{text(condition.value)}”</small>{/each}</td><td>{#each rows(row.actions) as action}<span class="cp-rule-action">{action.type==='setCategory'?`${m.l('Category','Categoría')}: ${m.category(action.value)}`:`${text(action.type)} ${text(action.value)}`}</span>{/each}</td><td><button class="cp-button ghost small" onclick={()=>a.edit('rules',row)}>{m.l('Edit rule','Editar regla')} →</button><button class="cp-link cp-red" onclick={()=>a.edit('rule-delete',row)}>{m.l('Delete','Eliminar')}</button></td></tr>{:else}<tr><td class="cp-empty" colspan="5">{m.l('Create your first categorization rule.','Crea tu primera regla de clasificación.')}</td></tr>{/each}</tbody></table></div></Panel>
{:else if m.route === 'reportes'}
  <div class="cp-tabs"><button class="active">{m.l('Overview','Vista general')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.l('Monthly income','Ingresos del mes')}</span><strong class="cp-cyan">{m.money(monthly.totalIncome)}</strong></div><div class="cp-stat"><span>{m.l('Monthly expenses','Gastos del mes')}</span><strong class="cp-red">{m.money(monthly.totalExpenses)}</strong></div><div class="cp-stat"><span>{m.l('Net cash flow','Flujo neto')}</span><strong class="cp-yellow">{m.money(n(monthly.totalIncome)-n(monthly.totalExpenses))}</strong></div></div>
  <div class="cp-two"><Panel title={m.l('Monthly cash flow','Flujo de efectivo mensual')}><div class="cp-legend"><span class="cp-cyan">■ {m.l('Income','Ingresos')}</span><span class="cp-red">■ {m.l('Expenses','Gastos')}</span></div><BarChart labels={m.trends.map(row=>text(row.month))} datasets={[{label:m.l('Income','Ingresos'),data:m.trends.map(row=>n(row.income)),backgroundColor:'#6ff4ed'},{label:m.l('Expenses','Gastos'),data:m.trends.map(row=>n(row.expenses)),backgroundColor:'#ff6b76'}]} height={220}/></Panel><Panel title={m.l('Net cash flow trend','Tendencia de flujo neto')}><LineChart labels={m.trends.map(row=>text(row.month))} datasets={[{label:m.l('Net cash flow','Flujo neto'),data:m.trends.map(row=>n(row.income)-n(row.expenses)),borderColor:'#6ff4ed',fill:true,backgroundColor:'#6ff4ed22'}]} height={250}/></Panel><Panel title={m.l('Spending by category','Gastos por categoría')}>{#each breakdown as row}<div class="cp-category-bar"><span>{text(row.categoryName)}</span><Meter value={n(row.percentage)} label={text(row.categoryName)} tone="red"/><strong class="cp-number">{m.money(row.total)}</strong></div>{:else}<p class="cp-empty">{m.l('No category spending this month.','No hay gastos por categoría este mes.')}</p>{/each}</Panel><Panel title={m.l('Income vs. expenses','Ingresos frente a gastos')}><table class="cp-table"><thead><tr><th>{m.l('Month','Mes')}</th><th>{m.l('Income','Ingresos')}</th><th>{m.l('Expenses','Gastos')}</th><th>{m.l('Savings','Ahorro')}</th></tr></thead><tbody>{#each m.trends as row}<tr><td>{text(row.month)}</td><td class="cp-number cp-cyan">{m.money(row.income)}</td><td class="cp-number cp-red">{m.money(row.expenses)}</td><td class="cp-number cp-yellow">{m.money(n(row.income)-n(row.expenses))}</td></tr>{/each}</tbody></table></Panel></div>
{:else}
  <div class="cp-toolbar"><div class="cp-tabs">{#each [['',m.l('All','Todas')],['critical',m.l('Urgent','Urgentes')],['warning',m.l('Upcoming','Próximas')],['info',m.l('Information','Información')]] as [value,label]}<button class:active={severity===value} onclick={()=>severity=value}>{label}</button>{/each}</div><select aria-label={m.l('Alert type','Tipo de alerta')} bind:value={alertType}><option value="">{$t('alerts.filter_type_all')}</option>{#each alertTypes as type}<option value={type}>{$t(`alerts.filter_${type}`)}</option>{/each}</select><button class="cp-button" disabled={evaluating} onclick={evaluate}>{evaluating?'…':$t('alerts.evaluate_now')}</button><button class="cp-button ghost" onclick={()=>read()}>{m.l('Mark all as read','Marcar todas como leídas')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.l('Need attention','Requieren atención')}</span><strong class="cp-red">{activeAlerts.filter(row=>text(row.severity).toLowerCase()==='critical').length}</strong></div><div class="cp-stat"><span>{m.l('Upcoming','Próximas')}</span><strong>{activeAlerts.filter(row=>text(row.severity).toLowerCase()==='warning').length}</strong></div><div class="cp-stat"><span>{m.l('Read','Leídas')}</span><strong class="cp-cyan">{m.alerts.filter(row=>row.isRead).length}</strong></div></div>
  <Panel title={m.l('Notifications','Notificaciones')}>{#snippet action()}<select aria-label={m.l('Read status','Estado de lectura')} bind:value={readFilter}><option value="">{m.l('All notifications','Todas')}</option><option value="unread">{m.l('Unread','Sin leer')}</option><option value="read">{m.l('Read','Leídas')}</option></select>{/snippet}<div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.l('Alert','Alerta')}</th><th>{m.l('Details','Detalles')}</th><th>{m.l('Date','Fecha')}</th><th>{m.l('Status','Estado')}</th><th></th></tr></thead><tbody>{#each visibleAlerts as row}<tr><td><Icon name={text(row.severity).toLowerCase()==='info'?'info':'alert-triangle'} size={23}/></td><td><button class="cp-text-button" onclick={()=>expanded=expanded===row.id?0:row.id}><b>{getAlertTitle(row, $t)}</b></button><p class="cp-muted">{getAlertMessage(row, $t)}</p>{#if expanded===row.id}<div class="cp-inline-actions"><button class="cp-link" onclick={()=>read(row.id)}>{m.l('Mark as read','Marcar leída')}</button><button class="cp-link cp-red" onclick={()=>remove(row.id)}>{m.l('Delete alert','Eliminar alerta')}</button></div>{/if}</td><td>{m.date(row.createdAt)}</td><td><span class="cp-badge" class:urgent={text(row.severity).toLowerCase()==='critical'}>{row.isRead?m.l('Read','Leída'):m.l('Unread','Sin leer')}</span></td><td><button class="cp-icon-button" aria-label={m.l('Alert actions','Acciones de alerta')} onclick={()=>expanded=expanded===row.id?0:row.id}>···</button></td></tr>{:else}<tr><td class="cp-empty" colspan="5">{m.l('You are all caught up.','Estás al día.')}</td></tr>{/each}</tbody></table></div></Panel>
{/if}
